import {COURSES,adaptiveAction} from './challenge-engine.js';
import {policyAction} from './agent.js';
const $=id=>document.getElementById(id);
export async function loadChallengeUI(onChange){
 const responses=await Promise.all([fetch('models/challenges.json'),fetch('models/training.json')]);if(responses.some(r=>!r.ok))throw new Error('Challenge data could not be loaded.');const [report,original]=await Promise.all(responses.map(r=>r.json()));
 let course='ramp',seedIndex=0,opponent='adapted',cp=report.checkpoints.at(-1),speed=4,mode='challenge';
 const base=original.checkpoints.at(-1),practice=original.checkpoints.find(c=>c.episode===10000);
 function context(){const q=cp.q;return {report,course,seed:report.testSeeds[seedIndex],seedIndex,opponent,checkpoint:cp.episode,speed:mode==='race'?1:speed,actionFor:opponent==='adapted'?e=>adaptiveAction(e,q):e=>policyAction(e,opponent==='classic'?base.q:practice.q),name:opponent==='adapted'?`Adapted · ${cp.episode.toLocaleString()} extra games`:opponent==='classic'?'Classic · 50,000 games':'Practice · 10,000 games'};}
 function chart(){const pts=report.curve.map(p=>{const m=p.metrics.find(m=>m.course===course);return `${35+p.episode/report.episodes*595},${86-m.meanSeconds/70*75}`;}).join(' ');$('adaptCurve').innerHTML=[0,20,40,60].map(n=>`<line x1="35" y1="${86-n/70*75}" x2="630" y2="${86-n/70*75}" stroke="#e0e7d7" stroke-dasharray="3 4"/><text x="25" y="${90-n/70*75}" text-anchor="end" font-size="8" fill="#a0b18e">${n}s</text>`).join('')+`<polyline points="${pts}" fill="none" stroke="#6e9561" stroke-width="2.3" stroke-linejoin="round"/><text x="35" y="106" font-size="8" fill="#9eaf8d">Transfer start</text><text x="630" y="106" text-anchor="end" font-size="8" fill="#9eaf8d">80,000 extra games</text>`;}
 function refresh(){const result=report.results.find(r=>r.course===course);$('beforeSeconds').textContent=result.baseline.meanSeconds.toFixed(1)+'s';$('afterSeconds').textContent=result.adapted.meanSeconds.toFixed(1)+'s';$('adaptGain').textContent='+'+Math.round((result.adapted.meanSeconds/result.baseline.meanSeconds-1)*100)+'%';$('courseCards').querySelectorAll('button').forEach(b=>{b.classList.toggle('selected',b.dataset.course===course);b.setAttribute('aria-pressed',String(b.dataset.course===course));});$('challengeCourse').value=course;$('adaptCheckpointLabel').hidden=opponent!=='adapted'||mode==='race';$('challengeSpeedLabel').hidden=mode==='race';$('adaptationResults').hidden=mode==='race';$('challengeTitle').innerHTML=mode==='race'?'Human instinct. <em>Machine timing.</em>':'Under a little <em>pressure.</em>';$('challengeEyebrow').textContent=mode==='race'?'ONE SKY. TWO PILOTS.':'THE SKY DOESN’T STAND STILL';$('challengeSubtitle').textContent=mode==='race'?'You are gold. AI is blue. The last bird flying wins.':'Faster pipes. Tighter gaps. Can the agent adapt?';$('launchChallenge').innerHTML=mode==='race'?'Start race <span>↗</span>':'Watch this agent <span>▷</span>';$('challengeExplanation').textContent=mode==='race'?'Space, ↑, click, or tap to flap your gold bird. Both birds face the same seeded pipes, moving gaps, and difficulty clock at 1× speed. The first crash ends the race; simultaneous crashes are a draw. P pauses both, R restarts the same course. A shared 180-second safety timeout is a draw.':'Summary: original Classic vs final policy after 80,000 extra games, on identical seeds and schedules. Checkpoint selection changes replay only. Some individual courses regress. Policies stay frozen while flying. No pipe cap; a crash or 180-second safety limit ends the run.';chart();}
 $('courseCards').innerHTML=Object.entries(COURSES).map(([id,c],i)=>`<button class="course-card" data-course="${id}" aria-pressed="false"><strong>${c.name}</strong><span>${c.description}</span><small>${i===2?'NO PIPE LIMIT · ALWAYS ESCALATING':'TIME-BASED DIFFICULTY'}</small></button>`).join('');$('courseCards').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{course=b.dataset.course;refresh();onChange(false);}));
 $('challengeRows').innerHTML=report.results.map(r=>`<tr><td>${COURSES[r.course].name}</td><td>${r.baseline.meanSeconds.toFixed(1)}s</td><td>${r.adapted.meanSeconds.toFixed(1)}s</td></tr>`).join('');
 $('challengeCourse').innerHTML=Object.entries(COURSES).map(([id,c])=>`<option value="${id}">${c.name}</option>`).join('');$('challengeCourse').addEventListener('change',e=>{course=e.target.value;refresh();onChange(false);});
 $('challengeSeed').innerHTML=report.testSeeds.map((s,i)=>`<option value="${i}">Course ${String(i+1).padStart(2,'0')} · seed ${s}</option>`).join('');$('challengeSeed').addEventListener('change',e=>{seedIndex=Number(e.target.value);onChange(false);});
 $('adaptCheckpoint').innerHTML=report.checkpoints.map(c=>`<option value="${c.id}">${c.episode.toLocaleString()} extra games</option>`).join('');$('adaptCheckpoint').value=cp.id;$('adaptCheckpoint').addEventListener('change',e=>{cp=report.checkpoints.find(c=>c.id===e.target.value);onChange(false);});
 $('challengeOpponent').addEventListener('change',e=>{opponent=e.target.value;refresh();onChange(false);});$('challengeSpeed').addEventListener('change',e=>{speed=Number(e.target.value);onChange(null);});$('launchChallenge').addEventListener('click',()=>onChange(true));
 $('challengeLoading').hidden=true;$('challengeContent').hidden=false;refresh();
 return {report,context,setMode(value){mode=value;if(mode==='race'){cp=report.checkpoints.at(-1);$('adaptCheckpoint').value=cp.id;}refresh();}};
}
